import{_ as r,C as a,o as i,c as n,E as o,a2 as s}from"./chunks/framework.BOeh4kYD.js";const g=JSON.parse('{"title":"Evidence: restriction enforcement and the check-to-effect interval","description":"","frontmatter":{"title":"Evidence: restriction enforcement and the check-to-effect interval","outline":"deep"},"headers":[],"relativePath":"en/research/evidence/2026-09-07-last-check-effect-boundary.md","filePath":"en/research/evidence/2026-09-07-last-check-effect-boundary.md","lastUpdated":1788773549000}'),c={name:"en/research/evidence/2026-09-07-last-check-effect-boundary.md"};function d(l,e,h,u,p,f){const t=a("ArticleTableScroll");return i(),n("div",null,[o(t,{language:"en"}),e[0]||(e[0]=s('<p><a href="/joinwell52/zh/research/evidence/2026-09-07-last-check-effect-boundary">中文</a> · <a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/last-check-evidence.zip" target="_blank" rel="noreferrer">Download evidence ZIP</a></p><h1 id="evidence-restriction-enforcement-and-the-check-to-effect-interval" tabindex="-1">Evidence: restriction enforcement and the check-to-effect interval <a class="header-anchor" href="#evidence-restriction-enforcement-and-the-check-to-effect-interval" aria-label="Permalink to &quot;Evidence: restriction enforcement and the check-to-effect interval&quot;">​</a></h1><p>Status: authorized by the user for public release with the articles on 2026-09-07. Chinese and English explanations refer to the same records. A package-check PASS is not product acceptance.</p><h2 id="evidence-chain" tabindex="-1">Evidence chain <a class="header-anchor" href="#evidence-chain" aria-label="Permalink to &quot;Evidence chain&quot;">​</a></h2><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/evidence/claims.json" target="_blank" rel="noreferrer">Claims</a> → <a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/evidence/sources.json" target="_blank" rel="noreferrer">source provenance</a> → <a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/evidence/observations.json" target="_blank" rel="noreferrer">de-identified observations</a> → this interpretation guide → <a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/evidence/check-records.mjs" target="_blank" rel="noreferrer">record checker</a> → <a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/evidence/manifest.json" target="_blank" rel="noreferrer">file hashes</a>.</p><p>The formal data was generated on 2026-09-07 at 07:35:09 UTC against product commit <code>c008d9db91a21136fc61a4f60314e22db395d5d2</code>. E0–E5 each have two rounds. Article one uses E0–E3 (eight observations), article two E4/E5 (four). The pilot is excluded; these are not two separate twelve-observation studies.</p><h2 id="reading-the-fields" tabindex="-1">Reading the fields <a class="header-anchor" href="#reading-the-fields" aria-label="Permalink to &quot;Reading the fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td>id / round</td><td>Scenario and repetition, each with a fresh synthetic directory</td></tr><tr><td>record_overwrite</td><td>Flag actually retained in the approval record, not an assumed UI configuration</td></tr><tr><td>status / error</td><td>Operation outcome, not the research process exit code</td></tr><tr><td>callback_calls</td><td>Executor callback entries, not a count of filesystem effects</td></tr><tr><td>target_bytes / target_digest</td><td>Synthetic bytes read after execution and their SHA-256</td></tr><tr><td>source_exists</td><td>Post-operation source-path existence; E0/E1 never create a source file</td></tr><tr><td>approved_source_digest</td><td>Approved source snapshot digest; null when no source exists in the scenario</td></tr><tr><td>after_evidence</td><td>Evidence returned by the executor; failed cases have none, and move reports moved rather than a fabricated copy-style digest</td></tr><tr><td>injection</td><td>Explicit researcher-induced source change inside E5&#39;s callback; null otherwise</td></tr></tbody></table><p>old-target, new-target, source-before, and source-after are the actual synthetic test strings. They are not replacements for undisclosed production file contents.</p><p>De-identification removes random fixture directories and absolute paths. Executor evidence uses source.txt/target.txt instead. Every formal row, status, error, byte string, digest, callback count, and injection label is retained. Approval fixture identities/tokens are not included. The original record&#39;s hash supports internal tracing, not independent verification of an unavailable original.</p><h2 id="checking-records-without-executing-the-product" tabindex="-1">Checking records without executing the product <a class="header-anchor" href="#checking-records-without-executing-the-product" aria-label="Permalink to &quot;Checking records without executing the product&quot;">​</a></h2><p>Run <code>node check-records.mjs</code> in this directory. It verifies twelve uniquely identified observations, repeatability of selected fields, byte digests, E4&#39;s zero callbacks, E5&#39;s digest mismatch, and the manifest files. Expected output: <code>EVIDENCE_RECORD_CHECK_PASS</code>.</p><p>That check preserves E1&#39;s failure, E4&#39;s stale rejection, and E2/E3&#39;s anomalous successes. It does not turn those outcomes into product acceptance.</p><h2 id="rerunning-the-actual-experiment" tabindex="-1">Rerunning the actual experiment <a class="header-anchor" href="#rerunning-the-actual-experiment" aria-label="Permalink to &quot;Rerunning the actual experiment&quot;">​</a></h2><p>The research harness is <code>probe-effects.mjs</code> in the parent research directory. It needs authorized access to product source and dependencies. This public package does not copy the product or claim that the record checker re-executes it.</p><p>Protocol in an authorized engineering environment: pin the stated commit; create isolated directories; construct requests with the real builder; use OperationApprovalService.prepare/approve/execute and the real executeWorkspaceOperation. E0–E3 disallow overwrite; E4/E5 permit it. E4 changes the source before rebuilding the current request. E5 changes it inside the research callback after approval validation. Read files and approval outcomes separately, using fresh directories in each round. Never run these scenarios on live approvals or business files.</p><p>Original research artifacts remain available locally for review. Publishing a portable harness requires a separate path/dependency accessibility check. This is not live end-to-end, multi-process contention, power-loss recovery, or independent QA evidence. No real accounts or remote-service effects were involved.</p><h2 id="source-and-scope-limits" tabindex="-1">Source and scope limits <a class="header-anchor" href="#source-and-scope-limits" aria-label="Permalink to &quot;Source and scope limits&quot;">​</a></h2><p>sources.json pins thirteen PR observations, including timestamps, base/head revisions, and merge state. Archiving them does not constitute independent testing. The articles mainly use Agents SDK #4893/#4894, Paperclip #12949, and GitHub MCP #3232; all were unmerged at the recorded time, the last one a Draft.</p><p>The fourth source_files entry—the executor registry—was inspected statically. The first three tested files retained their original hashes throughout the experiment. Git stores LF and the working copies use CRLF; content matches after newline normalization. Raw-byte inequality is not reported as a product change.</p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/last-check-boundary-20260907/evidence/README.zh.md" target="_blank" rel="noreferrer">中文说明</a></p>',21))])}const v=r(c,[["render",d]]);export{g as __pageData,v as default};
